                    )}
                </div>
            </div>
        </div>,
        document.body
    );
};

export default SwapFacultyModal;

import React, { createContext, useContext, useEffect, useState, useRef, useMemo } from 'react';
import { auth, db } from '../lib/firebase';
import {
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    signOut,
    onAuthStateChanged,
    sendPasswordResetEmail
} from 'firebase/auth';
import { doc, getDoc, setDoc, updateDoc, onSnapshot, collection, getDocs, query, where } from 'firebase/firestore';
// FlaskConical and Logo removed (unused)
import toast from 'react-hot-toast';
import { sendWhatsAppNotification } from '../utils/whatsappUtils';

const AuthContext = createContext({
    currentUser: null,
    userProfile: null,
    loading: true,
    login: async () => { },
    signup: async () => { },
    logout: async () => { },
    resetPassword: async () => { }
});

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => useContext(AuthContext);

const cleanYears = (years) => {
    if (!Array.isArray(years)) return [];

    // Normalize: Trim strings, deduplicate, and remove nulls/empty
    let unique = Array.from(new Set(
        years.filter(y => y).map(y => y.toString().trim())
    ));

    // Identify existing specific years (e.g. "2025-2026 (EVEN)")
    const specificYears = unique.filter(y => y.includes('('));
    const baseOfSpecific = specificYears.map(y => y.replace(/ \((ODD|EVEN)\)/i, '').trim());

    // Filter out plain base years if their specific version exists
    unique = unique.filter(y => {
        const isBase = !y.includes('(');
        const trimmedY = y.trim();
        // Keep non-base years OR base years whose specific version doesn't exist
        return !isBase || !baseOfSpecific.includes(trimmedY);
    });

    // Filter valid patterns (YYYY-YYYY), sort descending
    const valid = unique.filter(y => /^\d{4}-\d{4}/.test(y));
    return valid.sort().reverse();
};



const STORAGE_KEYS = {
    SELECTED_YEAR: 'lams_sel_year',
    SYSTEM_YEAR: 'lams_sys_year',
    ALL_YEARS: 'lams_all_years'
};

export const AuthProvider = ({ children }) => {
    // --- ROBUST STATE INITIALIZATION ---

    const [currentUser, setCurrentUser] = useState(null);
    const [userProfile, setUserProfile] = useState(null);

    // 3. State: Academic Years List (STRICT SERVER MODE)
    // IMPROVED: Try to hydrate from cache first to avoid content flashing, fall back to prediction.
    const [academicYears, setAcademicYears] = useState(() => {
        try {
            const cached = localStorage.getItem(STORAGE_KEYS.ALL_YEARS);
            if (cached) return JSON.parse(cached);
        } catch (e) {
            console.warn("Failed to parse cached years", e);
        }
        return [];
    });

    // 4. State: Active/System Year
    const [systemAcademicYear, setSystemAcademicYear] = useState(() => {
        const stored = localStorage.getItem(STORAGE_KEYS.SYSTEM_YEAR);
        return (stored && stored !== 'null') ? stored : null;
    });

    // 5. State: User Selection (Persist this, it's a user preference)
    const [selectedAcademicYear, setSelectedAcademicYear] = useState(() => {
        const stored = localStorage.getItem(STORAGE_KEYS.SELECTED_YEAR);
        return (stored && stored !== 'null') ? stored : null;
    });

    const [maxFacultyLoad, setMaxFacultyLoad] = useState(18);
    const [yearConfigs, setYearConfigs] = useState({});
    const [loading, setLoading] = useState(true);
    const [isSystemSyncing, setIsSystemSyncing] = useState(false); // Global Sync Shield
    const [isConfigLoaded, setIsConfigLoaded] = useState(false);

    const selectedAcademicYearRef = useRef(null);
    const previousSystemYear = useRef(null);

    // Initialize Ref from storage on mount (handling page reloads)
    useEffect(() => {
        previousSystemYear.current = localStorage.getItem(STORAGE_KEYS.SYSTEM_YEAR);
    }, []);

    // Keep Ref in sync with State
    useEffect(() => {
        selectedAcademicYearRef.current = selectedAcademicYear;
    }, [selectedAcademicYear]);

    const login = async (identifier, password) => {
        let email = identifier;
        if (!identifier.includes('@')) {
            try {
                const lookupDoc = await getDoc(doc(db, 'emp_lookups', identifier));
                if (lookupDoc.exists()) {
                    email = lookupDoc.data().email;
                } else {
                    console.warn(`EmpID ${identifier} not found in secure lookup.`);
                    throw new Error("Employee ID not linked. Please ask Admin to link your profile.");
                }
            } catch (err) {
                console.error("Login Lookup Error:", err);
                if (err.message.includes("not linked")) throw err;
                throw new Error("Login failed. Please use your Email Address.");
            }
        }
        return signInWithEmailAndPassword(auth, email, password);
    };

    const signup = async (empId, password, name, recoveryEmail, mobileNumber) => {
        const { user } = await createUserWithEmailAndPassword(auth, recoveryEmail, password);

        let isFirstUser = false;
        try {
            const usersSnapshot = await getDocs(collection(db, 'users'));
            isFirstUser = usersSnapshot.empty;
        } catch (e) {
            console.warn("First-user check failed, defaulting to pending user:", e);
        }

        let linkedDept = null;
        let isFaculty = false;
        let syncedPhotoURL = null;
        let syncedDesignation = null;
        let syncedShortCode = null;
        let syncedMobile = mobileNumber;
        
        try {
            let facultySnap = await getDocs(query(collection(db, 'faculty'), where('empId', '==', empId)));
            if (facultySnap.empty && recoveryEmail) {
                facultySnap = await getDocs(query(collection(db, 'faculty'), where('email', '==', recoveryEmail)));
            }
            if (!facultySnap.empty) {
                const facDoc = facultySnap.docs[0];
                const facData = facDoc.data();
                linkedDept = facData.department || facData.dept;
                isFaculty = true;
                if (facData.photoURL) syncedPhotoURL = facData.photoURL;
                if (facData.designation) syncedDesignation = facData.designation;
                if (facData.shortCode) syncedShortCode = facData.shortCode;
                if (facData.phone || facData.mobile) syncedMobile = facData.mobile || facData.phone;
                
                await updateDoc(doc(db, 'faculty', facDoc.id), {
                    uid: user.uid,
                    isRegistered: true,
                    email: recoveryEmail,
                    empId: empId
                });
            }
        } catch (facErr) {
            console.warn("Faculty lookup/link failed during signup:", facErr);
        }

        const userProfileData = {
            empId,
            name,
            email: recoveryEmail,
            mobile: syncedMobile,
            role: isFirstUser ? 'admin' : 'user',
            status: isFirstUser ? 'approved' : 'pending',
            dept: linkedDept,
            isFaculty: isFaculty,
            whatsappEnabled: true,
            createdAt: new Date().toISOString()
        };
        if (syncedPhotoURL) userProfileData.photoURL = syncedPhotoURL;
        if (syncedDesignation) userProfileData.designation = syncedDesignation;
        if (syncedShortCode) userProfileData.shortCode = syncedShortCode;

        // Always create user profile document in Firestore
        try {
            await setDoc(doc(db, 'users', user.uid), userProfileData);
        } catch (err) {
            console.error("Critical error creating Firestore profile:", err);
            // Rollback Auth User to prevent zombie accounts
            try {
                await user.delete();
            } catch (rollbackErr) {
                console.error("Failed to rollback auth user:", rollbackErr);
            }
            throw new Error("Failed to create user profile in database. Please try again.");
        }

        if (empId) {
            try {
                await setDoc(doc(db, 'emp_lookups', empId), { email: recoveryEmail, uid: user.uid });
            } catch (lookupErr) {
                console.warn("Emp lookup write failed:", lookupErr);
            }
        }

        // WhatsApp Notification on Signup
        if (mobileNumber) {
            try {
                const welcomeMsg = `🤖 *Welcome to LAMS* 🤖\n\nHi ${name},\nYour account has been successfully created and is pending approval.\n\n_You will receive updates directly on this number._`;
                sendWhatsAppNotification(mobileNumber, welcomeMsg);
            } catch (waErr) {
                console.warn("WhatsApp notification failed:", waErr);
            }
        }

        return user;
    };

    const resetPassword = (email) => {
        return sendPasswordResetEmail(auth, email);
    };

    const logout = () => {
        return signOut(auth);
    };

    const handleSetSelectedYear = (year) => {
        setSelectedAcademicYear(year);
        if (year) localStorage.setItem(STORAGE_KEYS.SELECTED_YEAR, year);
        else localStorage.removeItem(STORAGE_KEYS.SELECTED_YEAR);
    };

    const [allowUserYearChange, setAllowUserYearChange] = useState(false);

    // --- LOGIC: SYNC WITH SERVER CONFIG (The Single Source of Truth) ---
    // Switched to Real-Time (onSnapshot) to ensure new years appear instantly.
    useEffect(() => {
        if (!currentUser) return;

        const unsub = onSnapshot(doc(db, 'settings', 'config'), (docSnap) => {
            try {
                if (docSnap.exists()) {
                    setIsSystemSyncing(true); // TRIGGER LOADERS
                    const data = docSnap.data();

                    // A. Validate & Clean Server Data
                    const fetchedSystemYear = data.activeAcademicYear || null;
                    const fetchedYears = cleanYears(data.academicYears || []);
                    const fetchedConfigs = data.yearConfigs || {};
                    const fetchedAllowChange = data.allowUserYearChange || false;

                    // B. Source of Truth: Server Data + Active System Year.
                    const finalYears = cleanYears([...fetchedYears, fetchedSystemYear]);

                    // C. Update States
                    setSystemAcademicYear(fetchedSystemYear);
                    setAcademicYears(finalYears);
                    setYearConfigs(fetchedConfigs);
                    setAllowUserYearChange(fetchedAllowChange);

                    // D. Auto-Heal: If User Selection is now invalid (ghost), reset it
                    const currentSelection = localStorage.getItem(STORAGE_KEYS.SELECTED_YEAR);
                    if (currentSelection && !finalYears.includes(currentSelection)) {
                        console.warn(`Auto-Healing: Invalid selection ${currentSelection} removed.`);
                        setSelectedAcademicYear(null);
                        localStorage.removeItem(STORAGE_KEYS.SELECTED_YEAR);
                    }

                    // NEW ROBUST SYNC: Prevent Race Conditions across Tabs
                    // We compare against a Ref (memory) instead of localStorage (disk) inside the callback.
                    // This ensures EVERY active tab detects the change independently, even if another tab updated storage first.
                    if (previousSystemYear.current && previousSystemYear.current !== fetchedSystemYear) {
                        console.log(`System Year Change Detected (Ref): ${previousSystemYear.current} -> ${fetchedSystemYear}`);
                        setSelectedAcademicYear(null);
                        localStorage.removeItem(STORAGE_KEYS.SELECTED_YEAR);
                    }

                    // Update the Ref and Storage for next time
                    previousSystemYear.current = fetchedSystemYear;
                    if (fetchedSystemYear) {
                        localStorage.setItem(STORAGE_KEYS.SYSTEM_YEAR, fetchedSystemYear);
                    } else {
                        localStorage.removeItem(STORAGE_KEYS.SYSTEM_YEAR);
                    }

                    // E. Persistence
                    localStorage.setItem(STORAGE_KEYS.ALL_YEARS, JSON.stringify(finalYears));

                    // Short artificial delay to let contexts catch up visually
                    setTimeout(() => setIsSystemSyncing(false), 800);
                    setIsConfigLoaded(true);

                } else {
                    console.log("No Remote Config Found - Running in Offline/Fallback Mode");
                    const cachedSysYear = localStorage.getItem(STORAGE_KEYS.SYSTEM_YEAR);
                    const cachedAllYears = JSON.parse(localStorage.getItem(STORAGE_KEYS.ALL_YEARS) || '[]');
                    
                    if (cachedSysYear) {
                        setSystemAcademicYear(cachedSysYear);
                    }
                    if (cachedAllYears && cachedAllYears.length > 0) {
                        setAcademicYears(cachedAllYears);
                    }
                    setTimeout(() => setIsSystemSyncing(false), 800);
                    setIsConfigLoaded(true);
                }
            } catch (err) {
                console.error("Global Config Sync Error:", err);
                const cachedSysYear = localStorage.getItem(STORAGE_KEYS.SYSTEM_YEAR);
                if (cachedSysYear) setSystemAcademicYear(cachedSysYear);
                setIsSystemSyncing(false); // Force dismiss loader on error
                setIsConfigLoaded(true);
            }
        }, (err) => {
            console.error("Config Snapshot Error:", err);
            const cachedSysYear = localStorage.getItem(STORAGE_KEYS.SYSTEM_YEAR);
            const cachedAllYears = JSON.parse(localStorage.getItem(STORAGE_KEYS.ALL_YEARS) || '[]');
            if (cachedSysYear) setSystemAcademicYear(cachedSysYear);
            if (cachedAllYears && cachedAllYears.length > 0) setAcademicYears(cachedAllYears);
            setIsSystemSyncing(false); // Force dismiss loader on snapshot error
            setIsConfigLoaded(true);
        });

        return () => unsub();
    }, [currentUser]);

    // ENFORCE YEAR LOCK: Kick user back to Active Year if they are restricted
    useEffect(() => {
        if (!userProfile) return;
        const isAdmin = userProfile.role === 'admin';

        // If User is NOT Admin AND Year Change is DISABLED AND they are on a custom year
        if (!isAdmin && !allowUserYearChange && selectedAcademicYear) {
            console.log("Year Lock Enforced: Resetting user to System Year");
            setSelectedAcademicYear(null);
            localStorage.removeItem(STORAGE_KEYS.SELECTED_YEAR);
            toast("Year navigation is locked by Admin", { icon: '🔒', style: { borderRadius: '10px', background: '#333', color: '#fff' } });
        }
    }, [allowUserYearChange, userProfile, selectedAcademicYear]);

    // Update Max Load when Year or Configs Change
    useEffect(() => {
        const currentYear = selectedAcademicYear || systemAcademicYear;
        const currentConfig = yearConfigs[currentYear] || {};
        const maxLoad = currentConfig.maxFacultyLoad || 18;
        setMaxFacultyLoad(maxLoad);
    }, [selectedAcademicYear, systemAcademicYear, yearConfigs]);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (user) => {
            setCurrentUser(user);

            if (!user) {
                setLoading(false);
            }
        });

        // SAFETY: If Auth hangs (Limit Exhausted), force load after 7s to try offline mode
        const safetyTimer = setTimeout(() => {
            setLoading(prev => {
                if (prev) console.warn("Auth initialization timed out (Likely Firestore Limit). Forcing degraded mode.");
                setIsConfigLoaded(true); // Must also force this to true, otherwise value.loading stays true forever
                return false;
            });
        }, 7000);

        return () => {
            unsubscribe();
            clearTimeout(safetyTimer);
        };
    }, []);

    useEffect(() => {
        let unsubscribeProfile = () => { };

        if (currentUser) {
            // Using onSnapshot for Real-Time Role/Profile Updates
            // This allows Admins to Ban/Promote users instantly.
            if (!userProfile) setLoading(true);
            const docRef = doc(db, 'users', currentUser.uid);

            unsubscribeProfile = onSnapshot(docRef,
                (docSnap) => {
                    if (docSnap.exists()) {
                        const newData = docSnap.data();
                        setUserProfile(prev => {
                            if (!prev) return newData;
                            
                            // Prevent re-renders from background 'lastSeen' updates (Heartbeat)
                            // We ignore 'lastSeen', 'sessions', and 'isOnline'
                            const ignoreKeys = ['lastSeen', 'sessions', 'isOnline'];
                            const keys1 = Object.keys(prev).filter(k => !ignoreKeys.includes(k));
                            const keys2 = Object.keys(newData).filter(k => !ignoreKeys.includes(k));
                            
                            let isMeaningfulChange = keys1.length !== keys2.length;
                            if (!isMeaningfulChange) {
                                for (let key of keys1) {
                                    if (JSON.stringify(prev[key]) !== JSON.stringify(newData[key])) {
                                        isMeaningfulChange = true;
                                        break;
                                    }
                                }
                            }
                                
                            return isMeaningfulChange ? newData : prev;
                        });
                    } else {
                        console.warn("User Profile Missing!");
                        setUserProfile(null);
                    }
                    setLoading(false);
                },
                (err) => {
                    console.error("Profile Sync Error:", err);
                    setLoading(false);
                }
            );

        } else {
            setUserProfile(null);
        }

        return () => unsubscribeProfile();
    }, [currentUser]);

    const value = useMemo(() => ({
        currentUser,
        userProfile,
        activeAcademicYear: selectedAcademicYear || systemAcademicYear, // Fallback to system if null
        systemAcademicYear, // Expose system default if needed
        academicYears,
        maxFacultyLoad, // Expose the dynamic limit
        setSelectedAcademicYear: handleSetSelectedYear, // Allow changing view with persistence
        login,
        signup,
        resetPassword,
        logout,
        loading: loading || (currentUser && !isConfigLoaded),
        isSystemSyncing,
        allowUserYearChange // Expose the new setting
    }), [
        currentUser,
        userProfile,
        selectedAcademicYear,
        systemAcademicYear,
        academicYears,
        maxFacultyLoad,
        loading,
        isConfigLoaded,
        isSystemSyncing,
        allowUserYearChange
    ]);

    return (
        <AuthContext.Provider value={value}>
            {loading ? <div style={{ position:'fixed', inset:0, background:'#050505', zIndex:9999 }} /> : children}
        </AuthContext.Provider>
    );
};

import React, { createContext, useContext, useState, useEffect, useRef, useMemo } from 'react';
import { db } from '../lib/firebase';
import { collection, onSnapshot, query, where } from 'firebase/firestore';

import { useAuth } from './AuthContext';
import { parseTimeToDate } from '../utils/timeUtils';

const MasterDataContext = createContext();

// eslint-disable-next-line react-refresh/only-export-components
export const useMasterData = () => {
    return useContext(MasterDataContext);
};

export const MasterDataProvider = ({ children }) => {
    // Pull `loading` from AuthContext to gate our listeners until auth is fully settled.
    // This prevents the race condition where listeners fire before the user profile is resolved.
    const { currentUser, loading: authLoading } = useAuth();
    const [departments, setDepartments] = useState([]);
    const [semesters, setSemesters] = useState([]);
    const [subjects, setSubjects] = useState([]);
    const [faculty, setFaculty] = useState([]);
    const [rooms, setRooms] = useState([]);
    const [days, setDays] = useState([]);
    const [timeSlots, setTimeSlots] = useState([]);
    const [groups, setGroups] = useState([]);
    const [holidays, setHolidays] = useState([]);
    const [loading, setLoading] = useState(true);
    const [refreshTrigger, setRefreshTrigger] = useState(0);

    // Dynamic Refs for Quota-Safe Caching (Capture latest snapshot without stale closures)
    const departmentsRef = useRef([]);
    const semestersRef = useRef([]);
    const subjectsRef = useRef([]);
    const facultyRef = useRef([]);
    const roomsRef = useRef([]);
    const daysRef = useRef([]);
    const timeSlotsRef = useRef([]);
    const groupsRef = useRef([]);
    const holidaysRef = useRef([]);

    // Use a ref to track active unsubscribers so we can safely tear them down
    const unsubsRef = useRef([]);

    // Cleanup helper — call before setting up new listeners
    const cleanupListeners = () => {
        unsubsRef.current.forEach(u => {
            // eslint-disable-next-line sonarjs/no-ignored-exceptions, no-unused-vars
            try { u(); } catch (e) { /* ignore cleanup errors */ }
        });
        unsubsRef.current = [];
    };

    useEffect(() => {
        if (authLoading) return;

        // --- DYNAMIC HIBERNATION LOGIC ---
        // We stop all listeners when the tab is hidden to prevent "background leaks"
        // and re-sync only when the user returns.
        let isActive = true;
        let setupTimer = null;

        const syncMasterData = () => {
            if (!currentUser) {
                cleanupListeners();
                setDepartments([]); setSemesters([]); setSubjects([]); setFaculty([]);
                setRooms([]); setDays([]); setTimeSlots([]); setGroups([]); setHolidays([]);
                setLoading(false);
                return;
            }

            // TRY LOAD FROM CACHE FIRST (Instant UX)
            // eslint-disable-next-line sonarjs/no-ignored-exceptions
            try {
                const cache = JSON.parse(localStorage.getItem(`lams_master_cache_${currentUser.uid}`) || '{}');
                if (cache.faculty) {
                    setDepartments(cache.departments || []);
                    departmentsRef.current = cache.departments || [];
                    setSemesters(cache.semesters || []);
                    semestersRef.current = cache.semesters || [];
                    setSubjects(cache.subjects || []);
                    subjectsRef.current = cache.subjects || [];
                    setFaculty(cache.faculty || []);
                    facultyRef.current = cache.faculty || [];
                    setRooms(cache.rooms || []);
                    roomsRef.current = cache.rooms || [];
                    setDays(cache.days || []);
                    daysRef.current = cache.days || [];
                    setTimeSlots(cache.timeSlots || []);
                    timeSlotsRef.current = cache.timeSlots || [];
                    setGroups(cache.groups || []);
                    groupsRef.current = cache.groups || [];
                    setHolidays(cache.holidays || []);
                    holidaysRef.current = cache.holidays || [];
                    // We stay in "loading" state until live sync finishes, but UI has data!
                }
            } catch (e) { console.warn("Cache load failed"); }

            if (!departmentsRef.current || departmentsRef.current.length === 0) setLoading(true);
            cleanupListeners();

            const loadStatus = {
                departments: false, semesters: false, subjects: false, 
                faculty: false, rooms: false, days: false, 
                timeslots: false, groups: false, settings: false
            };

            const checkAllLoaded = () => {
                const allLoaded = Object.values(loadStatus).every(s => s);
                if (isActive && allLoaded) {
                    setLoading(false);
                    // UPDATE CACHE
                    const newCache = { 
                        departments: departmentsRef.current, 
                        semesters: semestersRef.current, 
                        subjects: subjectsRef.current, 
                        faculty: facultyRef.current, 
                        rooms: roomsRef.current, 
                        days: daysRef.current, 
                        timeSlots: timeSlotsRef.current, 
                        groups: groupsRef.current, 
                        holidays: holidaysRef.current 
                    };
                    localStorage.setItem(`lams_master_cache_${currentUser.uid}`, JSON.stringify(newCache));
                }
            };

            const naturalSort = (a, b) => {
                const splitAlphaNum = (str) => {
                    const match = String(str).match(/^(\D*)(\d+)(.*)$/);
                    if (!match) return [String(str), 0, ''];
                    return [match[1], parseInt(match[2] || 0, 10), match[3]];
                };
                const [aPre, aNum, aSuf] = splitAlphaNum(a);
                const [bPre, bNum, bSuf] = splitAlphaNum(b);
                const preCmp = aPre.localeCompare(bPre);
                if (preCmp !== 0) return preCmp;
                if (aNum !== bNum) return aNum - bNum;
                return aSuf.localeCompare(bSuf);
            };

            const setupListener = (collectionName, setState, statusKey, customQuery = null) => {
                const q = customQuery || query(collection(db, collectionName));
                const unsubscribe = onSnapshot(q, (snapshot) => {
                    if (!isActive) return;
                    const items = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
                    
                    // --- INTELLIGENT MASTER HUB SORT ---
                    if (statusKey === 'days') {
                        items.sort((a, b) => (a.order || 0) - (b.order || 0));
                    } else if (statusKey === 'timeslots') {
                        items.sort((a, b) => {
                            const t1 = parseTimeToDate(a.startTime).getTime();
                            const t2 = parseTimeToDate(b.startTime).getTime();
                            if (t1 !== t2) return t1 - t2;
                            return naturalSort(a.name || '', b.name || '');
                        });
                    } else if (statusKey === 'faculty') {
                        items.sort((a, b) => {
                            if (a.slNo !== undefined && b.slNo !== undefined) return a.slNo - b.slNo;
                            return naturalSort(a.name || '', b.name || '');
                        });
                    } else {
                        items.sort((a, b) => naturalSort(a.name || '', b.name || ''));
                    }
                    
                    // Check if data actually changed to prevent violent React re-renders on boot
                    let prevItems = [];
                    if (statusKey === 'departments') prevItems = departmentsRef.current;
                    else if (statusKey === 'semesters') prevItems = semestersRef.current;
                    else if (statusKey === 'subjects') prevItems = subjectsRef.current;
                    else if (statusKey === 'faculty') prevItems = facultyRef.current;
                    else if (statusKey === 'rooms') prevItems = roomsRef.current;
                    else if (statusKey === 'days') prevItems = daysRef.current;
                    else if (statusKey === 'timeslots') prevItems = timeSlotsRef.current;
                    else if (statusKey === 'groups') prevItems = groupsRef.current;
                    else if (statusKey === 'settings') prevItems = holidaysRef.current;

                    if (JSON.stringify(prevItems) !== JSON.stringify(items)) {
                        setState(items);
                        if (statusKey === 'departments') departmentsRef.current = items;
                        if (statusKey === 'semesters') semestersRef.current = items;
                        if (statusKey === 'subjects') subjectsRef.current = items;
                        if (statusKey === 'faculty') facultyRef.current = items;
                        if (statusKey === 'rooms') roomsRef.current = items;
                        if (statusKey === 'days') daysRef.current = items;
                        if (statusKey === 'timeslots') timeSlotsRef.current = items;
                        if (statusKey === 'groups') groupsRef.current = items;
                        if (statusKey === 'settings') holidaysRef.current = items;
                    }

                    loadStatus[statusKey] = true;
                    checkAllLoaded();
                }, (error) => {
                    console.warn(`[MasterData] Listener failed for ${collectionName}:`, error.code);
                    loadStatus[statusKey] = true;
                    checkAllLoaded();
                });
                unsubsRef.current.push(unsubscribe);
            };

            setupListener('departments', setDepartments, 'departments');
            setupListener('semesters', setSemesters, 'semesters');
            setupListener('subjects', setSubjects, 'subjects');
            setupListener('faculty', setFaculty, 'faculty');
            setupListener('rooms', setRooms, 'rooms');
            setupListener('days', setDays, 'days');
            setupListener('timeslots', setTimeSlots, 'timeslots');
            setupListener('groups', setGroups, 'groups');
            setupListener('settings', setHolidays, 'settings', query(collection(db, 'settings'), where('type', '==', 'holiday')));
        };

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'visible') {
                console.log("[MasterData] Focus detected. Resuming sync...");
                syncMasterData();
            } else {
                console.log("[MasterData] Background detected. Suspending sync for quota...");
                cleanupListeners();
            }
        };

        // Initial Start
        syncMasterData();
        document.addEventListener('visibilitychange', handleVisibilityChange);

        // SAFETY: If MasterData hangs (Limit Exhausted), force load after 8s to show cached data
        const masterSafetyTimer = setTimeout(() => {
            setLoading(prev => {
                if (prev) console.warn("MasterData initialization timed out. Forcing degraded mode.");
                return false;
            });
        }, 8000);

        return () => {
            isActive = false;
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            if (setupTimer) clearTimeout(setupTimer);
            clearTimeout(masterSafetyTimer);
            cleanupListeners();
        };
    }, [currentUser, authLoading, refreshTrigger]);

    // Force a re-fetch of all master data
    const refreshMasterData = async () => {
        setRefreshTrigger(prev => prev + 1);
    };

    const value = useMemo(() => ({
        departments,
        semesters,
        subjects,
        faculty,
        rooms,
        days,
        timeSlots,
        groups,
        holidays,
        loading,
        refreshMasterData
    }), [
        departments,
        semesters,
        subjects,
        faculty,
        rooms,
        days,
        timeSlots,
        groups,
        holidays,
        loading
    ]);

    return (
        <MasterDataContext.Provider value={value}>
            {children}
        </MasterDataContext.Provider>
    );
};

import React, { createContext, useContext, useEffect, useState, useRef, useMemo, useCallback } from 'react';
import { db, messaging } from '../lib/firebase';
import firebaseConfig from '../lib/firebaseConfig';
import { doc, updateDoc, arrayUnion, arrayRemove, deleteField } from 'firebase/firestore';
import { getToken, onMessage, deleteToken } from 'firebase/messaging';
import { useAuth } from './AuthContext';
import toast from 'react-hot-toast';

const NotificationContext = createContext();

// eslint-disable-next-line react-refresh/only-export-components
export const useNotifications = () => useContext(NotificationContext);

const ForegroundToast = ({ notification, t }) => {
    const data = notification.data || {};
    const primaryUrl = data?.url || '/';
    const title = notification.notification?.title || data?.title || 'Notification';
    const body = notification.notification?.body || data?.body || '';

    return (
        <div
            onClick={() => {
                if (primaryUrl) window.location.href = primaryUrl;
                toast.dismiss(t.id);
            }}
            className="glass-panel"
            style={{
                background: 'rgba(15, 23, 42, 0.95)',
                backdropFilter: 'blur(12px)',
                padding: '16px',
                borderRadius: '12px',
                border: '1px solid rgba(59, 130, 246, 0.4)',
                color: 'white',
                maxWidth: '380px',
                boxShadow: '0 20px 40px rgba(0,0,0,0.6)',
                display: 'flex',
                gap: '16px',
                cursor: 'pointer'
            }}
        >
            <div style={{ fontSize: '24px' }}>
                {data?.type === 'urgent' ? '🚨' : '🔔'}
            </div>
            <div>
                <div style={{ fontWeight: '700', color: '#60a5fa' }}>{title}</div>
                <div style={{ fontSize: '0.9rem', color: '#cbd5e1' }}>{body}</div>
            </div>
        </div>
    );
};

export const NotificationProvider = ({ children }) => {
    const { currentUser } = useAuth();
    const [initialized, setInitialized] = useState(false);
    const [permission, setPermission] = useState('Notification' in window ? Notification.permission : 'denied');
    const [fcmToken, setFcmToken] = useState(null);
    const lastLoginUid = useRef(null);
    const vapidKey = import.meta.env.VITE_FIREBASE_VAPID_KEY;

    // Helper: Register SW with config params and wait until active
    const registerFCMWorker = async (forceReinstall = false) => {
        if (!('serviceWorker' in navigator)) return null;
        try {
            if (forceReinstall) {
                const regs = await navigator.serviceWorker.getRegistrations();
                for (const reg of regs) {
                    await reg.unregister();
                }
                // Small delay to allow browser to clean up SW thread
                await new Promise(res => setTimeout(res, 500));
            }

            const params = new URLSearchParams();
            for (const [key, value] of Object.entries(firebaseConfig)) {
                if (value) params.append(key, value);
            }
            const swUrl = `/firebase-messaging-sw.js?${params.toString()}`;
            await navigator.serviceWorker.register(swUrl);

            // Wait for the Service Worker to be fully active before returning
            const registration = await navigator.serviceWorker.ready;
            return registration;
        } catch (error) {
            console.error("SW Registration failed:", error);
            return null;
        }
    };

    // 1. Initial Setup & Foreground Listener
    useEffect(() => {
        setInitialized(true);

        if (messaging) {
            try {
                onMessage(messaging, (payload) => {
                    toast.custom((t) => <ForegroundToast notification={payload} t={t} />, { duration: 8000, position: 'top-right' });
                });
            } catch (e) { console.warn("FCM onMessage error:", e); }
        }
    }, []);

    // 2. Handle User Identity (Sync & Auto-Healing)
    useEffect(() => {
        if (!initialized) return;

        const syncUser = async () => {
            if (currentUser?.uid) {
                lastLoginUid.current = currentUser.uid;

                // Auto-Heal: If permission is already granted, silently get token
                if ('Notification' in window && Notification.permission === 'granted' && messaging && vapidKey) {
                    let swReg;
                    let token;

                    try {
                        swReg = await registerFCMWorker();
                        token = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swReg });
                    } catch (e) {
                        console.warn("FCM initial sync failed, attempting self-heal...", e);
                        // Deep Self-Heal Protocol
                        try {
                            // Wipe the corrupted token from browser DB if possible
                            await deleteToken(messaging).catch(() => null);
                            // Violently purge all service workers
                            swReg = await registerFCMWorker(true);
                            // Attempt fresh token generation
                            token = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swReg });
                            console.log("FCM Self-heal successful. New token generated.");
                        } catch (healError) {
                            console.error("FCM Self-Heal completely failed:", healError);
                        }
                    }

                    if (token) {
                        setFcmToken(token);
                        let deviceId = localStorage.getItem('lams_device_id');
                        const updateData = {
                            fcmTokens: arrayUnion(token),
                            webPushActive: true,
                            lastSeen: new Date()
                        };
                        if (deviceId) {
                            updateData[`fcmDeviceTokens.${deviceId}`] = token;
                        }
                        await updateDoc(doc(db, 'users', currentUser.uid), updateData);
                    }
                }
            } else if (lastLoginUid.current) {
                // Logout logic: Delete the token locally and remotely
                try {
                    if (messaging && fcmToken) {
                        await deleteToken(messaging);

                        const removeData = {
                            fcmTokens: arrayRemove(fcmToken)
                        };
                        let deviceId = localStorage.getItem('lams_device_id');
                        if (deviceId) {
                            removeData[`fcmDeviceTokens.${deviceId}`] = deleteField();
                        }

                        await updateDoc(doc(db, 'users', lastLoginUid.current), removeData);
                        setFcmToken(null);
                    }
                } catch (e) {
                    console.warn("FCM Logout Cleanup Error:", e);
                } finally {
                    lastLoginUid.current = null;
                }
            }
        };

        syncUser();
    }, [currentUser, initialized, fcmToken, vapidKey]);

    const registerForPush = useCallback(async () => {
        if (!('Notification' in window) || !messaging) {
            toast.error("Push messaging not supported in this browser.");
            return;
        }
        if (!vapidKey) {
            toast.error("VAPID Key missing. Admin must configure VITE_FIREBASE_VAPID_KEY.");
            return;
        }

        try {
            const permissionResult = await Notification.requestPermission();
            setPermission(permissionResult);

            if (permissionResult === 'granted') {
                toast.loading("Generating Secure Key...", { id: 'push-register' });

                let swReg;
                let token;

                try {
                    swReg = await registerFCMWorker();
                    token = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swReg });
                } catch (e) {
                    console.warn("Manual push registration failed, self-healing...", e);
                    try {
                        await deleteToken(messaging).catch(() => null);
                        swReg = await registerFCMWorker(true);
                        token = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swReg });
                    } catch (healError) {
                        console.error("Manual push self-heal failed:", healError);
                        throw healError; // bubble to outer catch
                    }
                }

                if (token) {
                    setFcmToken(token);
                    if (currentUser?.uid) {
                        let deviceId = localStorage.getItem('lams_device_id');
                        const updateData = {
                            fcmTokens: arrayUnion(token),
                            webPushActive: true
                        };
                        if (deviceId) {
                            updateData[`fcmDeviceTokens.${deviceId}`] = token;
                        }
                        await updateDoc(doc(db, 'users', currentUser.uid), updateData);
                    }
                    toast.success("Notifications Enabled!", { id: 'push-register' });
                }
            } else {
                toast.error("Permission Denied. Please unblock in browser settings.");
            }
        } catch (e) { 
            console.error(e);
            toast.error("Failed to enable notifications.", { id: 'push-register' });
        }
    }, [currentUser, vapidKey]);

    const value = useMemo(() => ({ 
        registerForPush, 
        permission, 
        fcmToken, 
        initialized 
    }), [registerForPush, permission, fcmToken, initialized]);

    return (
        <NotificationContext.Provider value={value}>
            {children}
        </NotificationContext.Provider>
    );
};

import React, { createContext, useContext, useState, useEffect, useMemo } from 'react';
import { collection, query, where, onSnapshot, or, and } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { useAuth } from './AuthContext';

const ScheduleContext = createContext();

// eslint-disable-next-line react-refresh/only-export-components
export const useScheduleContext = () => useContext(ScheduleContext);

export const ScheduleProvider = ({ children }) => {
    const { currentUser, userProfile, activeAcademicYear, loading: authLoading } = useAuth();
    const [schedule, setSchedule] = useState([]);
    const scheduleRef = React.useRef([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        let unsubscribe = () => { };
        let isActive = true;

        const setupLiveSchedule = () => {
            // Don't flip loading=false if auth is still settling — prevents flash
            if (authLoading) return;

            if (!activeAcademicYear || typeof activeAcademicYear !== 'string' || !currentUser) {
                setSchedule([]);
                scheduleRef.current = [];
                setLoading(false); // ALWAYS drop loader if we abort
                return;
            }
            if (scheduleRef.current.length === 0) setLoading(true);

            try {
                const baseYear = activeAcademicYear.replace(/ \((ODD|EVEN)\)/i, '').trim();
                let searchYears = [activeAcademicYear];
                if (baseYear !== activeAcademicYear) searchYears.push(baseYear);
                else {
                    searchYears.push(`${baseYear} (EVEN)`);
                    searchYears.push(`${baseYear} (ODD)`);
                }
                searchYears = [...new Set(searchYears)];

                const isAdmin = userProfile?.role === 'admin';
                const empId = userProfile?.empId;
                let q;
                const scheduleRefDb = collection(db, 'schedule');

                // We query the entire schedule for the active academic year for ALL users.
                // This is critical because:
                // 1. Students need to see the full class schedule.
                // 2. Local conflict detection requires the full schedule to prevent double-booking rooms/faculty.
                q = query(scheduleRefDb, where('academicYear', 'in', searchYears));

                unsubscribe = onSnapshot(q, (snapshot) => {
                    if (!isActive) return;
                    const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
                    setSchedule(data);
                    scheduleRef.current = data;
                    setLoading(false);
                }, (err) => {
                    console.error("Critical Schedule Snapshot Error:", err);
                    setLoading(false);
                });

            } catch (e) {
                console.error("Setup Error:", e);
                setLoading(false);
            }
        };

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'visible') {
                console.log("[Schedule] Resuming live sync...");
                setupLiveSchedule();
            } else {
                console.log("[Schedule] Suspending sync for quota conservation...");
                unsubscribe();
            }
        };

        setupLiveSchedule();
        document.addEventListener('visibilitychange', handleVisibilityChange);

        return () => {
            isActive = false;
            unsubscribe();
            document.removeEventListener('visibilitychange', handleVisibilityChange);
        };
    }, [activeAcademicYear, currentUser, userProfile?.role, userProfile?.empId, authLoading]);

    // Manual refresh is no longer needed with real-time listeners, 
    // but kept as a stub to prevent breaking components that call it.
    const refreshSchedule = async () => {
        // console.debug("Schedule is live-synced. Manual refresh ignored.");
    };

    const value = useMemo(() => ({ schedule, loading, error, refreshSchedule }), [schedule, loading, error]);

    return (
        <ScheduleContext.Provider value={value}>
            {children}
        </ScheduleContext.Provider>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
