                    }
                    
                    .panel-header h3 {
                        font-size: 1.1rem !important;
                    }
                    
                    .panel-header .search-bar {
                        width: 100% !important;
                        max-width: 100% !important;
                    }
                    
                    /* Utility Classes */
                    .hide-mobile {
                        display: none !important;
                    }
                    
                    .mobile-small-text {
                        font-size: 0.8rem !important;
                    }
                    
                    .mobile-stack {
                        flex-direction: column !important;
                        align-items: flex-start !important;
                        gap: 1rem !important;
                    }
                    
                    /* Stat Cards - Smaller on Mobile */
                    .stat-card {
                        padding: 1rem !important;
                        gap: 1rem !important;
                    }
                    
                    .stat-card .icon-wrapper {
                        width: 40px !important;
                        height: 40px !important;
                    }
                    
                    .stat-card h3 {
                        font-size: 0.8rem !important;
                    }
                    
                    .stat-card p {
                        font-size: 1.5rem !important;
                    }
                    
                    /* Charts - Reduce Height on Mobile */
                    .chart-container {
                        padding: 1rem !important;
                        min-height: 250px !important;
                    }
                    
                    .chart-container h3 {
                        font-size: 0.95rem !important;
                        margin-bottom: 1rem !important;
                    }
                    
                    /* Analytics Grids - Single Column on Mobile */
                    .stats-grid {
                        grid-template-columns: repeat(2, 1fr) !important;
                        gap: 1rem !important;
                    }
                    
                    .charts-grid {
                        grid-template-columns: 1fr !important;
                        gap: 1rem !important;
                    }
                    
                    .analytics-grid, .charts-grid {
                        grid-template-columns: 1fr !important;
                        gap: 1rem !important;
                    }
                    
                    /* Force 1 column on very small factor for stats too */
                    @media (max-width: 480px) {
                        .stats-grid {
                            grid-template-columns: 1fr !important;
                        }
                    }
                    
                    /* Page Header - Stack on Mobile */
                    .page-header {
                        flex-direction: column !important;
                        align-items: flex-start !important;
                        gap: 1rem !important;
                        margin-bottom: 1.5rem !important;
                    }
                    
                    .page-header h1 {
                        font-size: 1.5rem !important;
                    }
                    
                    /* Tabs - Scrollable on Mobile */
                    .tabs-container {
                        gap: 0.5rem !important;
                        padding-bottom: 0.75rem !important;
                        margin-bottom: 1.5rem !important;
                        flex-wrap: nowrap !important;
                    }
                    
                    .tab-btn {
                        font-size: 0.9rem !important;
                        padding: 0.4rem 0.8rem !important;
                        white-space: nowrap;
                    }
                    
                    /* Glass Panel - Reduce Padding on Mobile */
                    .glass-panel {
                        padding: 1rem !important;
                    }
                    
                    /* Semester Popup - Mobile Fixes */
                    .semester-popup-overlay {
                        padding: 0 !important;
                        align-items: flex-end !important;
                    }
                    
                    .semester-popup-content {
                        max-width: 100% !important;
                        width: 100% !important;
                        max-height: 85vh !important;
                        border-bottom-left-radius: 0 !important;
                        border-bottom-right-radius: 0 !important;
                        border-radius: 20px 20px 0 0 !important;
