                                style={{ width: '100%', height: '56px', fontSize: '1.1rem' }}
                            >
                                {submitting ? <RefreshCw className="spin-animation" /> : <><Send size={20} /> Submit Application</>}
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
};

