// Main Component
// ─────────────────────────────────────────────
export default function StudentDirectory() {
  const { userProfile } = useAuth();
  const isAdmin = userProfile?.role === 'admin';
  const { groups = [], semesters = [] } = useMasterData();

  // Stats
  const [stats, setStats] = useState({ active: 0, groups: 0, alumni: 0, tc: 0 });
  const [statsLoading, setStatsLoading] = useState(true);

  // Filters
  const [search, setSearch] = useState('');
  const [filterBatch, setFilterBatch] = useState('');
  const [filterSemester, setFilterSemester] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  // Data
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(false);
  const unsubRef = useRef(null);

  // Selection
  const [selected, setSelected] = useState(new Set());
  const [bulkStatus, setBulkStatus] = useState('active');

  // Modals
  const [profileStudent, setProfileStudent] = useState(null);
  const [editStudent, setEditStudent] = useState(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [statusPopover, setStatusPopover] = useState(null);

  // ── Derive Batches dynamically from loaded students (Exact match with Attendance) ──
  const availableBatches = useMemo(() => {
    if (!students || students.length === 0) return [];
    const groupSet = new Set();
    students.forEach(s => {
        const sSection = (s.section || '').trim();
        const sGroup = String(s.group || '1').trim();
        const subStr = sSection ? sSection : (s.branch || '').trim();
        const badge = `${subStr}-${sGroup}`.toUpperCase();
        groupSet.add(badge);
    });
    return Array.from(groupSet).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  }, [students]);

  // ── Fetch stats on mount ──
  useEffect(() => {
    const fetchStats = async () => {
      setStatsLoading(true);
      try {
        const col = collection(db, 'students');
        const [activeSnap, alumniSnap, tcSnap] = await Promise.all([
          getCountFromServer(query(col, where('status', '==', 'active'))),
          getCountFromServer(query(col, where('status', '==', 'alumni'))),
          getCountFromServer(query(col, where('status', '==', 'tc'))),
        ]);
        setStats({
          active: activeSnap.data().count,
          groups: groups.length,
          alumni: alumniSnap.data().count,
          tc: tcSnap.data().count,
        });
      } catch (err) {
        console.error('Stats fetch error:', err);
      } finally {
        setStatsLoading(false);
      }
    };
    fetchStats();
  }, [groups.length]);

  // ── Real-time query ──
  useEffect(() => {
    if (unsubRef.current) { unsubRef.current(); unsubRef.current = null; }
    if (!filterBatch && !filterSemester) {
      setStudents([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    setSelected(new Set());
    const col = collection(db, 'students');
    let constraints = [];
    if (filterSemester) constraints.push(where('semester', '==', filterSemester));
    const q = query(col, ...constraints);
    unsubRef.current = onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ _id: d.id, ...d.data() }));
      data.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setStudents(data);
      setLoading(false);
    }, (err) => {
      console.error('Student query error:', err);
      toast.error('Failed to load students');
      setLoading(false);
    });
    return () => { if (unsubRef.current) unsubRef.current(); };
  }, [filterBatch, filterSemester]);

  // ── Filtered list ──
  const filteredStudents = useMemo(() => {
    let list = students || [];
    if (filterStatus !== 'all') list = list.filter(s => s.status === filterStatus);
    
    if (filterBatch) {
      const fb = filterBatch.toUpperCase();
      list = list.filter(s => {
        const sSection = (s.section || '').trim().toUpperCase();
        const sGroup = String(s.group || '1').trim().toUpperCase();
        const subStr = sSection ? sSection : (s.branch || '').trim().toUpperCase();
        const badge = `${subStr}-${sGroup}`;
        return sSection === fb || badge === fb;
      });
    }
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter(s =>
        (s.name || '').toLowerCase().includes(q) ||
        (s.regNo || '').toLowerCase().includes(q)
      );
    }
    return list;
  }, [students, filterStatus, search]);

  // ── Selection helpers ──
  const toggleSelect = (id) => setSelected(prev => {
    const n = new Set(prev);
    n.has(id) ? n.delete(id) : n.add(id);
    return n;
  });
  const toggleAll = () => {
    if (selected.size === filteredStudents.length) setSelected(new Set());
    else setSelected(new Set(filteredStudents.map(s => s._id)));
  };

  // ── Delete ──
  const handleDelete = async (student) => {
    if (!window.confirm(`Delete ${student.name}? This cannot be undone.`)) return;
    try {
      await deleteDoc(doc(db, 'students', student._id));
      toast.success('Student deleted');
    } catch { toast.error('Delete failed'); }
  };

  // ── Bulk Delete ──
  const handleBulkDelete = async () => {
    if (!window.confirm(`Delete ${selected.size} students? This cannot be undone.`)) return;
    try {
      const ids = [...selected];
      const chunks = chunkArray(ids, CHUNK_SIZE);
      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(id => batch.delete(doc(db, 'students', id)));
        await batch.commit();
      }
      toast.success(`${selected.size} students deleted`);
      setSelected(new Set());
    } catch { toast.error('Bulk delete failed'); }
  };

  // ── Delete Batch ──
  const handleDeleteBatch = async () => {
    if (!filterBatch) return;
    
    // Get ALL students in this batch regardless of search or status
    const batchStudents = (students || []).filter(s => {
      const fb = filterBatch.toUpperCase();
      const sSection = (s.section || '').trim().toUpperCase();
      const sGroup = String(s.group || '1').trim().toUpperCase();
      const subStr = sSection ? sSection : (s.branch || '').trim().toUpperCase();
      const badge = `${subStr}-${sGroup}`;
      return sSection === fb || badge === fb;
    });

    if (batchStudents.length === 0) {
      toast.error('No students found in this batch');
      return;
    }

    if (!window.confirm(`Are you sure you want to completely delete the ENTIRE "${filterBatch}" lab batch?\n\nThis will permanently delete ${batchStudents.length} students and cannot be undone.`)) return;
    
    if (window.prompt(`Type "DELETE" to confirm the deletion of ${filterBatch}`) !== 'DELETE') {
      toast.error('Deletion cancelled.');
      return;
    }

    try {
      const ids = batchStudents.map(s => s._id);
      const chunks = chunkArray(ids, CHUNK_SIZE);
      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(id => batch.delete(doc(db, 'students', id)));
        await batch.commit();
      }
      toast.success(`${ids.length} students deleted from ${filterBatch}`);
      setFilterBatch('');
      setSelected(new Set());
    } catch { toast.error('Failed to delete batch'); }
  };

  // ── Bulk Status Change ──
  const handleBulkStatus = async (newStatus) => {
    try {
      const ids = [...selected];
      
      const affectedCohorts = new Map();
      ids.forEach(id => {
        const student = students.find(s => s._id === id);
        if (student && student.status !== newStatus) {
            const key = `${student.semester}|${student.section}|${student.branch}`;
            affectedCohorts.set(key, { semester: student.semester, section: student.section, branch: student.branch });
        }
      });
      
      const chunks = chunkArray(ids, CHUNK_SIZE);
      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(id => batch.update(doc(db, 'students', id), { status: newStatus, updatedAt: new Date().toISOString() }));
        await batch.commit();
      }
      toast.success(`${selected.size} students set to ${STATUS_CONFIG[newStatus]?.label}`);
      setSelected(new Set());
      
      for (const cohort of affectedCohorts.values()) {
         rebalanceCohort(db, cohort.semester, cohort.section, cohort.branch).catch(err => console.error('Bulk rebalance failed:', err));
      }
    } catch { toast.error('Bulk status update failed'); }
  };

  // ── Export ──
  const handleExport = () => {
    if (filteredStudents.length === 0) { toast.error('No students to export'); return; }
    const data = filteredStudents.map(s => ({
      'Reg No': s.regNo, Name: s.name, Branch: s.branch,
      Semester: s.semester, 'Section/Batch': s.section,
      'Roll No': s.rollNo, Status: s.status, 'Lateral Entry': s.isLateral ? 'Yes' : 'No',
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Students');
    XLSX.writeFile(wb, `students_export_${Date.now()}.xlsx`);
    toast.success('Exported successfully');
  };

  const noFilter = !filterBatch && !filterSemester;

  return (
    <div style={{ minHeight: '100vh', color: '#f1f5f9', fontFamily: "'Inter', system-ui, sans-serif", padding: '16px 24px' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
        input::placeholder { color: #475569; }
        select option { background: #0f172a; color: #f1f5f9; }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 99px; }
        ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }
      `}</style>

      {/* Header */}
      <div style={{ marginBottom: 28, marginLeft: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 6 }}>
          <div style={{ width: 40, height: 40, borderRadius: 12, background: 'linear-gradient(135deg,#3b82f6,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 0 20px rgba(59,130,246,0.4)' }}>
            <Users size={20} color="#fff" />
          </div>
          <h1 style={{ margin: 0, fontSize: 26, fontWeight: 800, background: 'linear-gradient(135deg,#f1f5f9,#94a3b8)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
            Student Directory
          </h1>
        </div>
        <p style={{ margin: 0, color: '#64748b', fontSize: 14 }}>Manage, search and track all students in real-time</p>
      </div>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: 24, marginBottom: 32 }}>
        <StatCard icon={UserCheck} value={stats.active} label="Active Students" glow="#3b82f6" gradient="linear-gradient(135deg,#3b82f6,#1d4ed8)" loading={statsLoading} />
        <StatCard icon={BookOpen} value={stats.groups} label="Total Lab Batches" glow="#8b5cf6" gradient="linear-gradient(135deg,#8b5cf6,#6d28d9)" loading={statsLoading} />
        <StatCard icon={GraduationCap} value={stats.alumni} label="Alumni" glow="#10b981" gradient="linear-gradient(135deg,#10b981,#047857)" loading={statsLoading} />
        <StatCard icon={UserX} value={stats.tc} label="Transferred (TC)" glow="#ef4444" gradient="linear-gradient(135deg,#ef4444,#b91c1c)" loading={statsLoading} />
      </div>

      {/* Control Bar (Attendance Style) */}
      <div style={{
        display: 'flex', flexDirection: 'column', gap: '1.5rem',
        marginBottom: 24, padding: '2rem',
        background: 'rgba(15, 23, 42, 0.6)', border: '1px solid rgba(255,255,255,0.05)',
        borderRadius: '20px', backdropFilter: 'blur(16px)',
        boxShadow: '0 10px 30px -10px rgba(0,0,0,0.5)',
      }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem' }}>
              {/* Semester */}
              <div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#94a3b8', marginBottom: '8px', fontSize: '0.8rem', fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                      <span style={{ color: '#a855f7', fontSize: '1.2rem' }}>•</span> SEMESTER
                  </label>
                  <select style={{ width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(15,23,42,0.6)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.95rem', outline: 'none' }} value={filterSemester} onChange={e => { setFilterSemester(e.target.value); setFilterBatch(''); }}>
                      <option value="" style={{ background: '#0f172a' }}>— All Semesters —</option>
                      {semesters.map(s => <option key={s.id || s.number || s} value={s.number || s.name || s.value || s.id || s} style={{ background: '#0f172a' }}>{s.label || s.name || `Semester ${s.number || s.value || s}`}</option>)}
                  </select>
              </div>

              {/* Lab Batch */}
              <div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#94a3b8', marginBottom: '8px', fontSize: '0.8rem', fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                      <span style={{ color: '#10b981', fontSize: '1.2rem' }}>•</span> LAB BATCH / SUB-GROUP
                  </label>
                  <select 
                      style={{ width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(15,23,42,0.6)', border: filterSemester && !filterBatch ? '1px solid #3b82f6' : '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.95rem', outline: 'none' }} 
                      value={filterBatch} 
                      onChange={e => setFilterBatch(e.target.value)}
                      disabled={!filterSemester}
                  >
                      <option value="" style={{ background: '#0f172a' }}>{!filterSemester ? '— Select Semester First —' : '— All Lab Batches —'}</option>
                      {availableBatches.map(b => <option key={b} value={b} style={{ background: '#0f172a' }}>{b}</option>)}
                  </select>
              </div>

              {/* Status */}
              <div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#94a3b8', marginBottom: '8px', fontSize: '0.8rem', fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                      <span style={{ color: '#ef4444', fontSize: '1.2rem' }}>•</span> STATUS
                  </label>
                  <select style={{ width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(15,23,42,0.6)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.95rem', outline: 'none' }} value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
                      <option value="all" style={{ background: '#0f172a' }}>All Status</option>
                      <option value="active" style={{ background: '#0f172a' }}>Active</option>
                      <option value="alumni" style={{ background: '#0f172a' }}>Alumni</option>
                      <option value="tc" style={{ background: '#0f172a' }}>TC</option>
                  </select>
              </div>

              {/* Search */}
              <div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#94a3b8', marginBottom: '8px', fontSize: '0.8rem', fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                      <span style={{ color: '#3b82f6', fontSize: '1.2rem' }}>•</span> SEARCH
                  </label>
                  <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                      <Search size={18} color="#64748b" style={{ position: 'absolute', left: 14, pointerEvents: 'none' }} />
                      <input
                          value={search}
                          onChange={e => setSearch(e.target.value)}
                          placeholder="Search name or reg no…"
                          style={{
                              width: '100%', boxSizing: 'border-box', padding: '11px 14px 11px 40px', borderRadius: '12px', background: 'rgba(15,23,42,0.6)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.95rem', outline: 'none'
                          }}
                      />
                  </div>
              </div>
          </div>
          
          <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', flexWrap: 'wrap', marginTop: 8 }}>
            {isAdmin && filterBatch && (
              <Btn variant="danger" icon={Trash2} onClick={handleDeleteBatch} style={{ borderRadius: '12px', padding: '10px 18px', background: 'linear-gradient(135deg, #ef4444, #b91c1c)' }}>Delete Batch</Btn>
            )}
            {isAdmin && <Btn variant="primary" icon={Plus} onClick={() => setShowAddModal(true)} style={{ borderRadius: '12px', padding: '10px 18px', background: 'linear-gradient(135deg, #3b82f6, #0ea5e9)' }}>Add Student</Btn>}
            {isAdmin && <Btn variant="ghost" icon={Upload} onClick={() => setShowImport(true)} style={{ borderRadius: '12px', padding: '10px 18px' }}>Import</Btn>}
            <Btn variant="ghost" icon={Download} onClick={handleExport} style={{ borderRadius: '12px', padding: '10px 18px' }}>Export</Btn>
          </div>
      </div>

      {/* Bulk Action Bar */}
      {selected.size > 0 && (
        <div style={{
          display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap',
          padding: '14px 20px', marginBottom: 20,
          background: 'linear-gradient(90deg, rgba(59,130,246,0.1), rgba(6,182,212,0.05))',
          border: '1px solid rgba(59,130,246,0.3)',
          borderRadius: '16px', boxShadow: '0 8px 24px rgba(59,130,246,0.15)',
        }}>
          <span style={{ fontSize: '0.9rem', fontWeight: 700, color: '#60a5fa' }}>
            {selected.size} student{selected.size !== 1 ? 's' : ''} selected
          </span>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
            {isAdmin && (
              <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                <ControlSelect value={bulkStatus} onChange={setBulkStatus} style={{ minWidth: 160, background: 'rgba(0,0,0,0.3)' }}>
                  <option value="active">Set to Active</option>
                  <option value="alumni">Set to Alumni</option>
                  <option value="tc">Set to TC</option>
                </ControlSelect>
                <Btn variant="success" size="sm" icon={CheckCircle} onClick={() => handleBulkStatus(bulkStatus)}>Apply</Btn>
              </div>
            )}
            {isAdmin && (
              <Btn variant="danger" size="sm" icon={Trash2} onClick={handleBulkDelete}>Delete</Btn>
            )}
            <Btn variant="ghost" size="sm" icon={X} onClick={() => setSelected(new Set())}>Deselect All</Btn>
          </div>
        </div>
      )}

      {/* Table Area */}
      <div style={{
        background: 'rgba(15, 23, 42, 0.4)', border: '1px solid rgba(255,255,255,0.05)',
        borderRadius: '24px', overflow: 'hidden', backdropFilter: 'blur(16px)',
        boxShadow: '0 10px 40px -10px rgba(0,0,0,0.5)',
      }}>
        {/* Empty: no filter */}
        {noFilter && !loading && (
          <div style={{ padding: '60px 24px', textAlign: 'center' }}>
            <Filter size={48} color="#334155" style={{ marginBottom: 16 }} />
            <div style={{ fontSize: 18, fontWeight: 700, color: '#475569', marginBottom: 8 }}>Select a Lab Batch or Semester</div>
            <div style={{ fontSize: 14, color: '#334155' }}>Choose a lab batch or semester filter above to load students and avoid unnecessary reads.</div>
          </div>
        )}

        {/* Loading */}
        {loading && (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <tbody>{[...Array(8)].map((_, i) => <SkeletonRow key={i} />)}</tbody>
          </table>
        )}

        {/* Empty results */}
        {!noFilter && !loading && filteredStudents.length === 0 && (
          <div style={{ padding: '60px 24px', textAlign: 'center' }}>
            <AlertCircle size={48} color="#334155" style={{ marginBottom: 16 }} />
            <div style={{ fontSize: 18, fontWeight: 700, color: '#475569', marginBottom: 8 }}>No Students Found</div>
            <div style={{ fontSize: 14, color: '#334155' }}>
              {search ? `No results for "${search}"` : 'No students match the current filters.'}
            </div>
          </div>
        )}

        {/* Table */}
        {!noFilter && !loading && filteredStudents.length > 0 && (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr style={{ background: 'rgba(255, 255, 255, 0.02)', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
                  {isAdmin && (
                    <th style={{ padding: '16px', textAlign: 'center', width: 40 }}>
                      <input type="checkbox"
                        checked={selected.size === filteredStudents.length && filteredStudents.length > 0}
                        onChange={toggleAll}
                        style={{ accentColor: '#3b82f6', width: 16, height: 16, cursor: 'pointer' }}
                      />
                    </th>
                  )}
                  {['#', 'Student', 'Reg No', 'Branch', 'Sem', 'Lab Batch', 'Status', 'Actions'].map(h => (
                    <th key={h} style={{ padding: '16px', textAlign: 'left', color: '#94a3b8', fontWeight: 600, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', whiteSpace: 'nowrap' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filteredStudents.map((student, idx) => (
                  <tr key={student._id}
                    style={{
                      borderBottom: '1px solid rgba(255,255,255,0.03)',
                      transition: 'all 0.2s',
                      background: selected.has(student._id) ? 'rgba(59,130,246,0.08)' : 'transparent',
                    }}
                    onMouseEnter={e => { if (!selected.has(student._id)) { e.currentTarget.style.background = 'rgba(255,255,255,0.02)'; e.currentTarget.style.transform = 'translateY(-1px)'; } }}
                    onMouseLeave={e => { if (!selected.has(student._id)) { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.transform = 'none'; } }}
                  >
                    {/* Checkbox */}
                    {isAdmin && (
                      <td style={{ padding: '12px 16px', textAlign: 'center' }}>
                        <input type="checkbox"
                          checked={selected.has(student._id)}
                          onChange={() => toggleSelect(student._id)}
                          style={{ accentColor: '#3b82f6', width: 15, height: 15, cursor: 'pointer' }}
                        />
                      </td>
                    )}
                    {/* # */}
                    <td style={{ padding: '12px 16px', color: '#475569', fontWeight: 600 }}>{idx + 1}</td>
                    {/* Student */}
                    <td style={{ padding: '12px 16px' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <AvatarCircle name={student.name} size={34} />
                        <div>
                          <div style={{ fontWeight: 600, color: '#f1f5f9', display: 'flex', alignItems: 'center', gap: 6 }}>
                            {student.name}
                            {student.isLateral && (
                              <span style={{ fontSize: 10, padding: '2px 6px', borderRadius: 99, background: 'rgba(234,179,8,0.15)', border: '1px solid rgba(234,179,8,0.3)', color: '#eab308', fontWeight: 700 }}>L</span>
                            )}
                          </div>
                        </div>
                      </div>
                    </td>
                    {/* Reg No */}
                    <td style={{ padding: '12px 16px', fontFamily: 'monospace', color: '#94a3b8', fontSize: 12 }}>{student.regNo}</td>
                    {/* Branch */}
                    <td style={{ padding: '12px 16px', color: '#cbd5e1' }}>{student.branch || '—'}</td>
                    {/* Semester */}
                    <td style={{ padding: '12px 16px', color: '#94a3b8', textAlign: 'center' }}>{student.semester || '—'}</td>
                    {/* Section */}
                    <td style={{ padding: '12px 16px', color: '#94a3b8' }}>
                      {(() => {
                        const sSection = (student.section || '').trim();
                        const sGroup = String(student.group || '1').trim();
                        const subStr = sSection ? sSection : (student.branch || '').trim();
                        return subStr ? `${subStr}-${sGroup}`.toUpperCase() : '—';
                      })()}
                    </td>
                    {/* Status */}
                    <td style={{ padding: '12px 16px' }}>
                      <StatusBadge
                        status={student.status || 'active'}
                        isAdmin={isAdmin}
                        onClick={() => setStatusPopover(student)}
                      />
                    </td>
                    {/* Actions */}
                    <td style={{ padding: '12px 16px' }}>
                      <div style={{ display: 'flex', gap: 6 }}>
                        <button
                          onClick={() => setProfileStudent(student)}
                          title="View History"
                          style={{ background: 'rgba(59,130,246,0.12)', border: '1px solid rgba(59,130,246,0.2)', borderRadius: 7, padding: '5px 7px', cursor: 'pointer', color: '#60a5fa', display: 'flex', transition: 'all 0.15s' }}
                          onMouseEnter={e => (e.currentTarget.style.background = 'rgba(59,130,246,0.25)')}
                          onMouseLeave={e => (e.currentTarget.style.background = 'rgba(59,130,246,0.12)')}
                        >
                          <Eye size={14} />
                        </button>
                        {isAdmin && (
                          <>
                            <button
                              onClick={() => setEditStudent(student)}
                              title="Edit"
                              style={{ background: 'rgba(234,179,8,0.12)', border: '1px solid rgba(234,179,8,0.2)', borderRadius: 7, padding: '5px 7px', cursor: 'pointer', color: '#eab308', display: 'flex', transition: 'all 0.15s' }}
                              onMouseEnter={e => (e.currentTarget.style.background = 'rgba(234,179,8,0.25)')}
                              onMouseLeave={e => (e.currentTarget.style.background = 'rgba(234,179,8,0.12)')}
                            >
                              <Edit2 size={14} />
                            </button>
                            <button
                              onClick={() => handleDelete(student)}
                              title="Delete"
                              style={{ background: 'rgba(239,68,68,0.12)', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 7, padding: '5px 7px', cursor: 'pointer', color: '#ef4444', display: 'flex', transition: 'all 0.15s' }}
                              onMouseEnter={e => (e.currentTarget.style.background = 'rgba(239,68,68,0.25)')}
                              onMouseLeave={e => (e.currentTarget.style.background = 'rgba(239,68,68,0.12)')}
                            >
                              <Trash2 size={14} />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Table Footer */}
        {!noFilter && !loading && filteredStudents.length > 0 && (
          <div style={{
            padding: '12px 20px', borderTop: '1px solid rgba(255,255,255,0.05)',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            background: 'rgba(255,255,255,0.02)',
          }}>
            <span style={{ fontSize: 12.5, color: '#475569' }}>
              Showing <strong style={{ color: '#94a3b8' }}>{filteredStudents.length}</strong> of <strong style={{ color: '#94a3b8' }}>{students.length}</strong> students
            </span>
            <span style={{ fontSize: 12, color: '#334155' }}>
              {filterBatch && `Batch: ${filterBatch}`}{filterBatch && filterSemester && ' · '}{filterSemester && `Sem: ${filterSemester}`}
            </span>
          </div>
        )}
      </div>

      {/* Modals */}
      {profileStudent && <ProfileModal student={profileStudent} onClose={() => setProfileStudent(null)} />}

      {statusPopover && (
        <StatusPopover
          student={statusPopover}
          onClose={() => setStatusPopover(null)}
          onChanged={() => setStatusPopover(null)}
        />
      )}

      {(showAddModal || editStudent) && (
        <AddEditModal
          student={editStudent}
          groups={groups}
          availableBatches={availableBatches}
          semesters={semesters}
          students={students}
          onClose={() => { setShowAddModal(false); setEditStudent(null); }}
          onSaved={() => { setShowAddModal(false); setEditStudent(null); }}
        />
      )}

      {showImport && (
        <ImportModal
          semesters={semesters}
          onClose={() => setShowImport(false)}
          onImported={() => setShowImport(false)}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { db } from '../../lib/firebase';
import { collection, query, where, getDocs, doc, writeBatch } from 'firebase/firestore';
import { useMasterData } from '../../contexts/MasterDataContext';
import { useAuth } from '../../contexts/AuthContext';
import QuantumLoader from '../../components/QuantumLoader';
import { ArrowRight, ShieldAlert, History, Users } from 'lucide-react';
import toast from 'react-hot-toast';

const processStudent = (student, batch, mode, targetSem, targetGroup, activeAcademicYear, clearRollNos) => {
    const studentRef = doc(db, 'students', student.id);
    const historyRecord = {
        academicYear: activeAcademicYear || 'Unknown',
        semester: student.semester,
        section: student.section || student.branch || '',
        group: student.group || '1',
        rollNo: student.rollNo || student.rollno || null,
        timestamp: new Date().toISOString()
    };

    const newHistory = Array.isArray(student.academicHistory)
        ? [...student.academicHistory, historyRecord]
        : [historyRecord];

    if (mode === 'graduate') {
        batch.update(studentRef, {
            status: 'alumni',
            academicHistory: newHistory,
            graduatedAt: new Date().toISOString()
        });
    } else {
        const updatePayload = {
            semester: targetSem.toString(),
            ...(targetGroup ? { section: targetGroup } : {}),
            academicHistory: newHistory,
            updatedAt: new Date().toISOString()
        };
        
        if (clearRollNos) {
            updatePayload.rollNo = '';
        }
        
        batch.update(studentRef, updatePayload);
    }
};

const StudentPromotions = () => {
    const { semesters, groups } = useMasterData();
    const { activeAcademicYear } = useAuth();

    const [fromSem, setFromSem] = useState('');
    const [fromGroup, setFromGroup] = useState(''); // optional — leave blank = ALL batches
    const [targetSem, setTargetSem] = useState('');
    const [targetGroup, setTargetGroup] = useState(''); // optional — leave blank = keep existing section
    const [mode, setMode] = useState('promote'); // promote | graduate

    const [eligibleStudents, setEligibleStudents] = useState([]);
    const [selectedIds, setSelectedIds] = useState(new Set());
    const [loading, setLoading] = useState(false);
    const [processing, setProcessing] = useState(false);
    const [clearRollNos, setClearRollNos] = useState(false);

    const [dbSections, setDbSections] = useState([]);
    const [loadingBatches, setLoadingBatches] = useState(false);

    React.useEffect(() => {
        if (!fromSem) {
            setDbSections([]);
            return;
        }
        const fetchSections = async () => {
            setLoadingBatches(true);
            try {
                const q = query(collection(db, 'students'), where('semester', '==', fromSem.toString()), where('status', '==', 'active'));
                const snap = await getDocs(q);
                const secSet = new Set();
                snap.forEach(doc => {
                    const s = doc.data();
                    const sSection = (s.section || '').trim();
                    const subStr = sSection ? sSection : (s.branch || '').trim();
                    if (subStr) secSet.add(subStr);
                });
                setDbSections(Array.from(secSet).sort());
            } catch (err) {
                console.error(err);
            } finally {
                setLoadingBatches(false);
            }
        };
        fetchSections();
    }, [fromSem]);

    const handleFetchEligible = async () => {
        if (!fromSem) {
            toast.error("Please select a Current Semester first.");
            return;
        }

        setLoading(true);
        try {
            const studentRef = collection(db, 'students');

            // If a specific batch is chosen, filter by it. Otherwise, load ALL of that semester.
            const q = fromGroup
                ? query(studentRef, where('semester', '==', fromSem.toString()), where('section', '==', fromGroup))
                : query(studentRef, where('semester', '==', fromSem.toString()));

            const snapshot = await getDocs(q);

            const data = snapshot.docs
                .map(d => ({ id: d.id, ...d.data() }))
                .filter(s => s.status === 'active')
                .sort((a, b) => {
                    const secA = a.section || a.branch || 'Unknown';
                    const secB = b.section || b.branch || 'Unknown';
                    const secCompare = secA.localeCompare(secB);
                    if (secCompare !== 0) return secCompare;
                    
                    const grpA = String(a.group || '1');
                    const grpB = String(b.group || '1');
                    const grpCompare = grpA.localeCompare(grpB);
                    if (grpCompare !== 0) return grpCompare;
                    
                    return (a.regNo || '').localeCompare(b.regNo || '');
                });

            setEligibleStudents(data);
            setSelectedIds(new Set(data.map(s => s.id)));

            // Auto-detect graduation
            if (parseInt(fromSem) >= 8) setMode('graduate');
            else setMode('promote');

            if (data.length === 0) toast.error("No active students found for this selection.");
            else toast.success(`Found ${data.length} eligible students across ${new Set(data.map(s => s.section || s.branch)).size} section(s).`);

        } catch (error) {
            toast.error("Failed to fetch eligible students.");
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleExecute = async () => {
        if (selectedIds.size === 0) return;
        if (mode === 'promote' && !targetSem) {
            toast.error("Please select a Target Semester.");
            return;
        }

        const batchNote = targetGroup ? `to ${targetGroup}` : `(keeping their existing section)`;
        if (!window.confirm(
            `Promote ${selectedIds.size} students to Sem ${targetSem} ${batchNote}?\n\nTheir current Sem/Section/Group will be saved to academic history before updating.${clearRollNos ? '\n\nWARNING: Roll Numbers will be cleared for the promoted students!' : ''}`
        )) return;

        setProcessing(true);
        try {
            const selectedStudents = eligibleStudents.filter(s => selectedIds.has(s.id));

            // Chunk into groups of 400 (Firestore batch limit is 500)
            for (let i = 0; i < selectedStudents.length; i += 400) {
                const chunk = selectedStudents.slice(i, i + 400);
                const batch = writeBatch(db);

                for (const student of chunk) {
                    processStudent(student, batch, mode, targetSem, targetGroup, activeAcademicYear, clearRollNos);
                }

                await batch.commit();
            }

            toast.success(`✅ ${mode === 'graduate' ? 'Graduated' : 'Promoted'} ${selectedIds.size} students successfully!`);
            setEligibleStudents([]);
            setSelectedIds(new Set());
            setFromSem('');
            setFromGroup('');
            setTargetSem('');
            setTargetGroup('');
        } catch (error) {
            toast.error("Promotion failed. Please try again.");
            console.error(error);
        } finally {
            setProcessing(false);
        }
    };

    // Group students by section for display
    const studentsBySection = eligibleStudents.reduce((acc, s) => {
        const sec = s.section || s.branch || 'Unknown';
        const grp = s.group || '1';
        const key = `${sec} - Group ${grp}`;
        if (!acc[key]) acc[key] = [];
        acc[key].push(s);
        return acc;
    }, {});

    const getExecuteButtonBg = () => {
        if (selectedIds.size === 0 || (mode === 'promote' && !targetSem)) return 'rgba(255,255,255,0.05)';
        if (mode === 'graduate') return 'linear-gradient(135deg, #8b5cf6, #c084fc)';
        return 'linear-gradient(135deg, #3b82f6, #06b6d4)';
    };

    const getExecuteButtonText = () => {
        if (processing) return 'Processing...';
        const actionName = mode === 'graduate' ? 'Graduation' : 'Promotion';
        return `Execute ${actionName} (${selectedIds.size})`;
    };

    const getRowBg = (s, idx) => {
        if (selectedIds.has(s.id)) return 'rgba(59,130,246,0.07)';
        if (idx % 2 === 0) return 'transparent';
        return 'rgba(255,255,255,0.008)';
    };

    return (
        <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '2rem', height: '100%', overflowY: 'auto', boxSizing: 'border-box' }}>

            {/* Info Banner */}
            <div style={{ background: 'linear-gradient(135deg, rgba(245, 158, 11, 0.1), rgba(217, 119, 6, 0.05))', border: '1px solid rgba(245, 158, 11, 0.2)', padding: '1.25rem 1.75rem', borderRadius: '20px', display: 'flex', gap: '1.25rem', alignItems: 'flex-start', boxShadow: '0 8px 32px rgba(245, 158, 11, 0.05)' }}>
                <ShieldAlert color="#f59e0b" size={24} style={{ flexShrink: 0, marginTop: '2px', filter: 'drop-shadow(0 2px 4px rgba(245, 158, 11, 0.3))' }} />
                <div>
                    <h4 style={{ color: '#fbbf24', margin: '0 0 0.5rem', fontWeight: 800, fontSize: '1rem', letterSpacing: '0.01em' }}>Academic History Vault Active</h4>
                    <p style={{ margin: 0, color: '#fcd34d', fontSize: '0.88rem', lineHeight: 1.6, opacity: 0.9 }}>
                        Before any student is updated, their <b>current Semester, Section, Group, and Roll No</b> is safely stored in their academic history record ({activeAcademicYear || 'Unknown'}).
                        If you leave <b>Target Section blank</b>, each student keeps their existing section and group — only the semester number changes.
                    </p>
                </div>
            </div>

            {/* Selection Engine */}
            <div className="glass-panel" style={{ 
                padding: '1.25rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem',
                background: 'rgba(15, 23, 42, 0.4)', border: '1px solid rgba(255, 255, 255, 0.05)', 
                borderRadius: '24px', backdropFilter: 'blur(16px)', boxShadow: '0 10px 40px -10px rgba(0,0,0,0.5)'
            }}>

                {/* FROM */}
                <div style={{ background: 'rgba(0,0,0,0.25)', padding: '1.25rem', borderRadius: '16px', border: '1px dashed rgba(255,255,255,0.08)', position: 'relative', boxSizing: 'border-box' }}>
                    <div style={{ display: 'inline-block', background: '#1e293b', padding: '2px 12px', fontSize: '0.8rem', color: '#64748b', fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase', borderRadius: '8px', marginBottom: '1rem' }}>Current State</div>
                    <h3 style={{ color: '#94a3b8', margin: '0 0 1.5rem', fontSize: '1.05rem', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600 }}>
                        <History size={18} /> Will be vaulted
                    </h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                        <div>
                            <label style={{ display: 'block', color: '#94a3b8', marginBottom: '8px', fontSize: '0.82rem', fontWeight: 600, letterSpacing: '0.05em', textTransform: 'uppercase' }}>Current Semester <span style={{ color: '#f87171' }}>*</span></label>
                            <select style={{ boxSizing: 'border-box', width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.9rem', outline: 'none' }} value={fromSem} onChange={e => { setFromSem(e.target.value); setEligibleStudents([]); setSelectedIds(new Set()); }}>
                                <option value="" style={{ background: '#0f172a' }}>— Select Semester —</option>
                                {semesters.map(s => <option key={s.id} value={s.number} style={{ background: '#0f172a' }}>Sem {s.number}</option>)}
                            </select>
                        </div>
                        <div>
                            <label style={{ display: 'block', color: '#94a3b8', marginBottom: '8px', fontSize: '0.82rem', fontWeight: 600, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                                Filter by Section {loadingBatches && <span style={{ color: '#60a5fa', textTransform: 'none', marginLeft: '4px' }}>(loading...)</span>}
                                <span style={{ marginLeft: '10px', fontSize: '0.7rem', background: 'rgba(59,130,246,0.15)', color: '#60a5fa', padding: '4px 8px', borderRadius: '10px', textTransform: 'none' }}>Optional — blank = ALL sections</span>
                            </label>
                            <input 
                                style={{ boxSizing: 'border-box', width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.9rem', outline: 'none' }} 
                                value={fromGroup} 
                                onChange={e => { setFromGroup(e.target.value); setEligibleStudents([]); setSelectedIds(new Set()); }}
                                list="promoSectionList"
                                placeholder="Select or type Section"
                            />
                            <datalist id="promoSectionList">
                                {Array.from(new Set([...dbSections, ...(groups?.map(g => g.name) || [])])).sort().map(s => <option key={s} value={s} />)}
                            </datalist>
                        </div>
                        <button
                            onClick={handleFetchEligible}
                            disabled={loading || !fromSem}
                            style={{ padding: '14px', background: fromSem ? 'rgba(59,130,246,0.15)' : 'rgba(255,255,255,0.03)', color: fromSem ? '#60a5fa' : '#475569', border: `1px solid ${fromSem ? 'rgba(59,130,246,0.3)' : 'rgba(255,255,255,0.05)'}`, borderRadius: '12px', cursor: fromSem ? 'pointer' : 'not-allowed', marginTop: '0.5rem', fontWeight: 700, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', transition: 'all 0.2s', boxShadow: fromSem ? '0 4px 12px rgba(59,130,246,0.1)' : 'none' }}
                        >
                            {loading ? <QuantumLoader size={20} /> : <><Users size={18} /> Fetch Eligible Students</>}
                        </button>
                    </div>
                </div>

                {/* TO */}
                <div style={{ background: 'linear-gradient(135deg, rgba(59, 130, 246, 0.06), rgba(6, 182, 212, 0.03))', padding: '1.25rem', borderRadius: '16px', border: '1px solid rgba(59, 130, 246, 0.2)', position: 'relative', boxSizing: 'border-box' }}>
                    <div style={{ display: 'inline-block', background: 'linear-gradient(135deg, #3b82f6, #06b6d4)', padding: '2px 14px', fontSize: '0.8rem', color: '#fff', fontWeight: 800, letterSpacing: '0.05em', textTransform: 'uppercase', borderRadius: '8px', boxShadow: '0 4px 12px rgba(59,130,246,0.4)', marginBottom: '1rem' }}>Target State</div>
                    
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                        <h3 style={{ color: '#60a5fa', margin: 0, fontSize: '1.05rem', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600 }}>
                            <ArrowRight size={18} /> Moving to
                        </h3>
                        <div style={{ display: 'flex', background: 'rgba(0,0,0,0.3)', borderRadius: '10px', padding: '4px', gap: '4px', border: '1px solid rgba(255,255,255,0.05)' }}>
                            <button onClick={() => setMode('promote')} style={{ padding: '6px 16px', background: mode === 'promote' ? '#3b82f6' : 'transparent', color: mode === 'promote' ? 'white' : '#94a3b8', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 700, transition: 'all 0.2s' }}>Promote</button>
                            <button onClick={() => setMode('graduate')} style={{ padding: '6px 16px', background: mode === 'graduate' ? '#8b5cf6' : 'transparent', color: mode === 'graduate' ? 'white' : '#94a3b8', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 700, transition: 'all 0.2s' }}>Graduate</button>
                        </div>
                    </div>

                    {mode === 'promote' ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                            <div>
                                <label style={{ display: 'block', color: '#94a3b8', marginBottom: '8px', fontSize: '0.82rem', fontWeight: 600, letterSpacing: '0.05em', textTransform: 'uppercase' }}>Target Semester <span style={{ color: '#f87171' }}>*</span></label>
                                <select style={{ boxSizing: 'border-box', width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.9rem', outline: 'none' }} value={targetSem} onChange={e => setTargetSem(e.target.value)}>
                                    <option value="" style={{ background: '#0f172a' }}>— Select Target Semester —</option>
                                    {semesters.map(s => <option key={s.id} value={s.number} style={{ background: '#0f172a' }}>Sem {s.number}</option>)}
                                </select>
                            </div>
                            <div>
                                <label style={{ display: 'block', color: '#94a3b8', marginBottom: '8px', fontSize: '0.82rem', fontWeight: 600, letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                                    Target Section
                                    <span style={{ marginLeft: '10px', fontSize: '0.7rem', background: 'rgba(16,185,129,0.1)', color: '#34d399', padding: '4px 8px', borderRadius: '10px', textTransform: 'none' }}>Optional — blank = keep existing</span>
                                </label>
                                <input 
                                    style={{ boxSizing: 'border-box', width: '100%', padding: '12px 14px', borderRadius: '12px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.1)', color: '#f8fafc', fontSize: '0.9rem', outline: 'none' }} 
                                    value={targetGroup} 
                                    onChange={e => setTargetGroup(e.target.value)}
                                    list="promoSectionList"
                                    placeholder="Leave blank to keep existing"
                                />
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginTop: '0.5rem' }}>
                                <input
                                    type="checkbox"
                                    id="clearRollNosCheck"
                                    checked={clearRollNos}
                                    onChange={e => setClearRollNos(e.target.checked)}
                                    style={{ width: 16, height: 16, accentColor: '#f43f5e', cursor: 'pointer' }}
                                />
                                <label htmlFor="clearRollNosCheck" style={{ fontSize: '0.85rem', color: clearRollNos ? '#f43f5e' : '#94a3b8', cursor: 'pointer', fontWeight: 500, transition: 'color 0.2s' }}>
                                    Clear Roll Numbers on Promotion (Useful if re-assigning next semester)
                                </label>
                            </div>
                            {targetSem && !targetGroup && (
                                <div style={{ background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.2)', borderRadius: '12px', padding: '12px 16px', fontSize: '0.85rem', color: '#6ee7b7', lineHeight: 1.5, marginTop: '0.5rem', display: 'flex', gap: '10px' }}>
                                    <span style={{ fontSize: '1rem' }}>✅</span>
                                    <div>
                                        Students move to <b>Sem {targetSem}</b> and remain in their <b>current section & group</b>.
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div style={{ padding: '3rem 2rem', textAlign: 'center', background: 'rgba(139,92,246,0.05)', borderRadius: '16px', border: '1px solid rgba(139,92,246,0.1)' }}>
                            <div style={{ fontSize: '3rem', marginBottom: '1.25rem', filter: 'drop-shadow(0 4px 12px rgba(139,92,246,0.4))' }}>🎓</div>
                            <p style={{ color: '#c4b5fd', fontSize: '0.95rem', lineHeight: 1.6, margin: 0, fontWeight: 500 }}>
                                Selected students will be marked as <b>Alumni</b> and excluded from all active searches and attendance sheets.
                            </p>
                        </div>
                    )}
                </div>
            </div>

            {/* Student List grouped by section */}
            {eligibleStudents.length > 0 && (
                <div className="glass-panel" style={{ 
                    padding: 0, overflow: 'hidden',
                    background: 'rgba(15, 23, 42, 0.4)', border: '1px solid rgba(255, 255, 255, 0.05)', 
                    borderRadius: '24px', backdropFilter: 'blur(16px)', boxShadow: '0 10px 40px -10px rgba(0,0,0,0.5)'
                }}>
                    {/* Action Bar */}
                    <div style={{ padding: '1.25rem', borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'linear-gradient(to right, rgba(0,0,0,0.3), rgba(0,0,0,0.1))', flexWrap: 'wrap', gap: '1rem' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', flexWrap: 'wrap' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                <div style={{ background: 'rgba(59,130,246,0.2)', border: '1px solid rgba(59,130,246,0.3)', width: 36, height: 36, borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                    <Users size={18} color="#60a5fa" />
                                </div>
                                <span style={{ color: 'white', fontWeight: 800, fontSize: '1.1rem' }}>
                                    {selectedIds.size} <span style={{ color: '#64748b', fontWeight: 500 }}>/ {eligibleStudents.length} selected</span>
                                </span>
                            </div>
                            <div style={{ display: 'flex', gap: '8px' }}>
                                <button onClick={() => setSelectedIds(new Set(eligibleStudents.map(s => s.id)))} style={{ padding: '6px 14px', fontSize: '0.85rem', background: 'rgba(59,130,246,0.15)', color: '#60a5fa', border: '1px solid rgba(59,130,246,0.3)', borderRadius: '8px', cursor: 'pointer', fontWeight: 600, transition: 'all 0.2s' }}>Select All</button>
                                <button onClick={() => setSelectedIds(new Set())} style={{ padding: '6px 14px', fontSize: '0.85rem', background: 'rgba(255,255,255,0.05)', color: '#94a3b8', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', cursor: 'pointer', fontWeight: 600, transition: 'all 0.2s' }}>Deselect All</button>
                            </div>
                        </div>
                        <button
                            onClick={handleExecute}
                            disabled={processing || selectedIds.size === 0 || (mode === 'promote' && !targetSem)}
                            style={{
                                padding: '12px 32px',
                                background: getExecuteButtonBg(),
                                color: (selectedIds.size === 0 || (mode === 'promote' && !targetSem)) ? '#64748b' : 'white',
                                border: 'none',
                                borderRadius: '14px',
                                fontWeight: 800,
                                fontSize: '0.95rem',
                                cursor: (selectedIds.size > 0 && (mode !== 'promote' || targetSem)) ? 'pointer' : 'not-allowed',
                                opacity: processing ? 0.6 : 1,
                                transition: 'all 0.2s',
                                boxShadow: (selectedIds.size > 0 && (mode !== 'promote' || targetSem)) ? '0 8px 24px rgba(59,130,246,0.3)' : 'none'
                            }}
                        >
                            {getExecuteButtonText()}
                        </button>
                    </div>

                    {/* Grouped by Section */}
                    <div style={{ maxHeight: '600px', overflowY: 'auto', overflowX: 'auto' }}>
                        {Object.entries(studentsBySection).map(([section, sectionStudents]) => {
                            const allSelected = sectionStudents.every(s => selectedIds.has(s.id));
                            const someSelected = sectionStudents.some(s => selectedIds.has(s.id));
                            return (
                                <div key={section}>
                                    {/* Section Header */}
                                    <div style={{ padding: '0.8rem 2rem', background: 'rgba(59,130,246,0.08)', borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', gap: '1rem', position: 'sticky', top: 0, zIndex: 5, backdropFilter: 'blur(10px)' }}>
                                        <input
                                            type="checkbox"
                                            checked={allSelected}
                                            ref={el => { if (el) el.indeterminate = someSelected && !allSelected; }}
                                            onChange={e => {
                                                const newSet = new Set(selectedIds);
                                                sectionStudents.forEach(s => e.target.checked ? newSet.add(s.id) : newSet.delete(s.id));
                                                setSelectedIds(newSet);
                                            }}
                                            style={{ accentColor: '#3b82f6', width: '18px', height: '18px', cursor: 'pointer' }}
                                        />
                                        <span style={{ fontWeight: 800, color: '#60a5fa', fontSize: '0.9rem', letterSpacing: '0.05em', textTransform: 'uppercase' }}>
                                            {section}
                                        </span>
                                        <span style={{ background: 'rgba(59,130,246,0.15)', border: '1px solid rgba(59,130,246,0.3)', color: '#93c5fd', padding: '4px 12px', borderRadius: '20px', fontSize: '0.8rem', fontWeight: 600 }}>
                                            {sectionStudents.filter(s => selectedIds.has(s.id)).length} / {sectionStudents.length} selected
                                        </span>
                                    </div>
                                    {/* Students in this section */}
                                    <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                        <tbody>
                                            {sectionStudents.map((s, idx) => (
                                                <tr
                                                    key={s.id}
                                                    onClick={() => {
                                                        const newSet = new Set(selectedIds);
                                                        if (newSet.has(s.id)) newSet.delete(s.id);
                                                        else newSet.add(s.id);
                                                        setSelectedIds(newSet);
                                                    }}
                                                    style={{
                                                        borderBottom: '1px solid rgba(255,255,255,0.025)',
                                                        cursor: 'pointer',
                                                        background: getRowBg(s, idx),
                                                        transition: 'background 0.15s'
                                                    }}
                                                >
                                                    <td style={{ padding: '1rem 2rem', width: '60px' }}>
                                                        <input type="checkbox" checked={selectedIds.has(s.id)} readOnly style={{ accentColor: '#3b82f6', width: '18px', height: '18px', pointerEvents: 'none' }} />
                                                    </td>
                                                    <td style={{ padding: '1rem', fontFamily: 'monospace', color: '#94a3b8', fontSize: '0.9rem', width: '180px' }}>{s.regNo}</td>
                                                    <td style={{ padding: '1rem', color: 'white', fontWeight: 600 }}>{s.name}</td>
                                                    <td style={{ padding: '1rem', color: '#64748b', fontSize: '0.9rem', textAlign: 'right', paddingRight: '2rem' }}>Roll: {s.rollNo || s.rollno || '--'}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

